
const K='FIREBDTOUR_NEON_DATA_V2',ADMIN='wisshakib@gmail.com',PASS='shakib1111';
const BASEIMG={"banner": "data:image/jpeg;base64,", "br": "data:image/jpeg;base64,", "solo": "data:image/jpeg;base64,", "squad": "data:image/jpeg;base64,", "cs": "data:image/jpeg;base64,", "lone": "data:image/jpeg;base64,", "give": "data:image/jpeg;base64,"};
const LOGO='data:image/jpeg;base64,';
const CATS=[['br','BR MATCH'],['solo','BR SURVIVAL'],['squad','CLASH SQUAD'],['cs','CS 2 VS 2'],['lone','LONE WOLF'],['give','FREE MATCH GIVEAWAY']];
function D(){let d=JSON.parse(localStorage.getItem(K)||JSON.stringify({users:[],matches:[],deposits:[],withdrawals:[],settings:{bkash:{available:true,number:'01333413567',color:'#e21378'},nagad:{available:false,number:'',color:'#f28c18'},rocket:{available:false,number:'',color:'#6d35c9'}}}));d.settings=d.settings||{};for(const k of ['bkash','nagad','rocket'])d.settings[k]={available:false,number:'',color:k==='bkash'?'#e21378':k==='nagad'?'#f28c18':'#6d35c9',...(d.settings[k]||{})};return d}
function S(d){localStorage.setItem(K,JSON.stringify(d))}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function money(n){return '৳'+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2})}
function imgFor(d,k){return (d.images&&d.images[k])||BASEIMG[k]||''}
function login(){document.body.innerHTML=`<div class="login"><div class="loginbox"><img src="${LOGO}"><h1>ADMIN PANEL</h1><p>FIREBDTOUR Tournament Management</p><input id="ae" class="input" placeholder="Admin Gmail"><input id="ap" class="input" type="password" placeholder="Password" style="margin-top:8px"><button class="btn primary" style="width:100%;margin-top:10px" onclick="doLogin()">LOGIN TO ADMIN</button><div id="lm" class="loginmsg"></div></div></div>`}
function doLogin(){if((ae.value||'').trim().toLowerCase()!==ADMIN||ap.value!==PASS){lm.textContent='Wrong admin email or password';return}localStorage.setItem('adminok','1');render('dashboard')}
function shell(active,title,body){let d=D();document.body.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><img src="${LOGO}"><div><b>FIREBDTOUR</b><small>ADMIN PANEL</small></div></div><div class="navtitle">MAIN</div><div class="nav">
<button class="${active==='dashboard'?'on':''}" onclick="render('dashboard')"><span class="ico">▣</span><span>Dashboard</span></button>
<button class="${active==='add'?'on':''}" onclick="render('add')"><span class="ico">＋</span><span>Add Match</span></button>
<button class="${active==='matches'?'on':''}" onclick="render('matches')"><span class="ico">🎮</span><span>Manage Matches</span></button>
<button class="${active==='players'?'on':''}" onclick="render('players')"><span class="ico">♟</span><span>Players</span></button>
<button class="${active==='deposits'?'on':''}" onclick="render('deposits')"><span class="ico">💳</span><span>Deposits</span></button>
<button class="${active==='withdraws'?'on':''}" onclick="render('withdraws')"><span class="ico">💸</span><span>Withdraws</span></button>
<button class="${active==='payment'?'on':''}" onclick="render('payment')"><span class="ico">⚙</span><span>Payment Settings</span></button><button class="${active==='redeem'?'on':''}" onclick="render('redeem')"><span class="ico">🎟️</span><span>Redeem Codes</span></button><button class="${active==='give'?'on':''}" onclick="render('give')"><span class="ico">💰</span><span>Give Money</span></button><button class="${active==='deduct'?'on':''}" onclick="render('deduct')"><span class="ico">➖</span><span>Deduct Money</span></button>
<button class="${active==='images'?'on':''}" onclick="render('images')"><span class="ico">🖼</span><span>Category Images</span></button>
<button class="${active==='settings'?'on':''}" onclick="render('settings')"><span class="ico">☷</span><span>Settings</span></button>
<button class="logout" onclick="localStorage.removeItem('adminok');login()"><span class="ico">↪</span><span>Logout</span></button></div></aside><main class="main"><header class="topbar"><div><h1>${title}</h1><div class="sub">FIREBDTOUR Tournament Management System</div></div><div class="adminuser"><div class="email">wisshakib@gmail.com<br><small style="color:#8f879f">Administrator</small></div><div class="avatar">W</div></div></header><div class="content">${body}</div></main></div>`}
function stats(d){let dep=d.deposits||[],wd=d.withdrawals||[];let totalDep=dep.filter(x=>x.status==='approved').reduce((a,x)=>a+Number(x.amount||0),0);let totalWd=wd.filter(x=>x.status==='approved').reduce((a,x)=>a+Number(x.amount||0),0);return `<div class="stats"><div class="stat"><div class="label">TOTAL USERS</div><b>${d.users.length}</b><div class="tag">Registered players</div></div><div class="stat"><div class="label">TOTAL MATCHES</div><b>${d.matches.length}</b><div class="tag">All categories</div></div><div class="stat"><div class="label">TOTAL DEPOSITS</div><b>${money(totalDep)}</b><div class="tag">Approved deposits</div></div><div class="stat"><div class="label">TOTAL WITHDRAWS</div><b>${money(totalWd)}</b><div class="tag">Approved withdrawals</div></div></div>`}
function dashboard(){let d=D(),pendingD=(d.deposits||[]).filter(x=>x.status==='pending'),pendingW=(d.withdrawals||[]).filter(x=>x.status==='pending');let recent=d.matches.slice(-5).reverse();return shell('dashboard','Dashboard',`${stats(d)}<div class="grid"><div class="card"><h2>ADD MATCH</h2><form id="quickForm" class="formgrid"><div><label class="label">CATEGORY</label><select name="c" class="select">${CATS.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select></div><div><label class="label">MATCH TITLE</label><input name="t" class="input" placeholder="Ultra BR Match" required></div><div><label class="label">ENTRY FEE (৳)</label><input name="e" class="input" type="number" min="0" required></div><div><label class="label">PRIZE POOL (৳)</label><input name="p" class="input" type="number" min="0" required></div><div><label class="label">TOTAL SLOTS</label><input name="max" class="input" type="number" min="1" value="48" required></div><div><label class="label">PER KILL (৳)</label><input name="kill" class="input" type="number" min="0" value="0"></div><div><label class="label">START TIME</label><input name="st" class="input" type="datetime-local" required></div><div><label class="label">ROOM RELEASE TIME</label><input name="rel" class="input" type="datetime-local" required></div><div><label class="label">ROOM ID</label><input name="ri" class="input" placeholder="Can add later"></div><div><label class="label">ROOM PASSWORD</label><input name="rp" class="input" placeholder="Can add later"></div><div class="full actions"><button class="btn primary">ADD MATCH</button><button type="button" class="btn ghost" onclick="render('add')">OPEN FULL FORM</button></div></form></div><div class="rightstack"><div class="card"><h3>PENDING QUEUE</h3><div class="matchline"><span>Deposits</span><b>${pendingD.length}</b></div><div class="matchline"><span>Withdraws</span><b>${pendingW.length}</b></div><div class="actions" style="margin-top:10px"><button class="btn mini green" onclick="render('deposits')">VIEW DEPOSITS</button><button class="btn mini orange" onclick="render('withdraws')">VIEW WITHDRAWS</button></div></div><div class="card"><h3>PAYMENT METHOD SETTINGS</h3>${paymentMini(d)}</div></div></div><div class="card section"><div class="row" style="display:flex;justify-content:space-between;align-items:center"><h3 style="margin:0">RECENT MATCHES</h3><button class="btn ghost mini" onclick="render('matches')">MANAGE ALL</button></div>${recent.length?recent.map(m=>`<div class="matchline"><span><b>${esc(m.title)}</b><br><small class="muted">${catName(m.category)} · ${money(m.entry)} · ${m.players?.length||m.buyers?.length||0}/${m.max||48}</small></span><span class="pill ${new Date(m.startAt||0)>new Date()?'active':'closed'}">${new Date(m.startAt||0)>new Date()?'OPEN':'ENDED'}</span></div>`).join(''):'<div class="empty">No matches added yet.</div>'}</div>`)}
function paymentMini(d){return ['bkash','nagad','rocket'].map(k=>{let s=d.settings[k];return `<div class="setting"><div class="row"><span><b>${k.toUpperCase()}</b><br><small class="muted">${esc(s.number||'Not set')}</small></span><span class="pill ${s.available?'active':'closed'}">${s.available?'Enabled':'Disabled'}</span></div></div>`}).join('')}
function catName(k){return (CATS.find(c=>c[0]===k)||['',k])[1]}
function add(){return shell('add','Add Match',`<div class="card"><h2>FIRST ADD MATCH</h2><p class="muted">Admin এখানে match তৈরি করলে user panel-এর সেই category-তে match card দেখা যাবে।</p><form id="addForm" class="formgrid"><div><label class="label">MATCH NAME</label><input class="input" name="t" placeholder="Ultra BR Match" required></div><div><label class="label">CATEGORY</label><select class="select" name="c">${CATS.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select></div><div><label class="label">ENTRY FEE (৳)</label><input class="input" name="e" type="number" min="0" required></div><div><label class="label">WIN PRIZE / PRIZE POOL (৳)</label><input class="input" name="p" type="number" min="0" required></div><div><label class="label">MAX PLAYERS</label><input class="input" name="max" type="number" min="1" value="48" required></div><div><label class="label">PER KILL (৳)</label><input class="input" name="kill" type="number" min="0" value="0"></div><div><label class="label">START TIME</label><input class="input" name="st" type="datetime-local" required></div><div><label class="label">ROOM RELEASE TIME</label><input class="input" name="rel" type="datetime-local" required></div><div><label class="label">ROOM ID</label><input class="input" name="ri" placeholder="Room ID"></div><div><label class="label">ROOM PASSWORD</label><input class="input" name="rp" placeholder="Room Password"></div><div><label class="label">ENTRY TYPE</label><select class="select" name="et"><option value="Solo">Solo</option><option value="Duo">Duo</option><option value="Squad">Squad</option></select></div><div><label class="label">MINIMUM LEVEL (0 = NO BAN)</label><input class="input" name="minLevel" type="number" min="0" value="0"></div><div><label class="label">MAP</label><input class="input" name="map" value="Bermuda"></div><div><label class="label">VERSION</label><input class="input" name="ver" value="MOBILE"></div><div><label class="label">IMAGE LABEL</label><input class="input" name="it" value="FREE FIRE"></div><div class="full"><label class="label">MATCH IMAGE (OPTIONAL)</label><input class="file" name="image" type="file" accept="image/*"></div><div class="full actions"><button class="btn primary">ADD MATCH</button><button type="button" class="btn ghost" onclick="render('dashboard')">CANCEL</button></div></form></div>`)}
function saveMatch(form){let f=new FormData(form),d=D();let m={id:'m'+Date.now(),title:f.get('t'),category:f.get('c'),entry:Number(f.get('e')||0),prize:Number(f.get('p')||0),max:Number(f.get('max')||48),kill:Number(f.get('kill')||0),startAt:new Date(f.get('st')).getTime(),releaseAt:new Date(f.get('rel')).getTime(),roomId:String(f.get('ri')||'').trim(),roomPass:String(f.get('rp')||'').trim(),roomPassword:String(f.get('rp')||'').trim(),entryType:f.get('et')||'Solo',minLevel:Number(f.get('minLevel')||0),map:f.get('map')||'Bermuda',version:f.get('ver')||'MOBILE',imageText:f.get('it')||'FREE FIRE',buyers:[],players:[],resultPublished:false,status:'open'};let file=form.querySelector('input[name=image]')?.files?.[0];if(file){let r=new FileReader();r.onload=()=>{m.image=r.result;d.matches.push(m);S(d);alert('Match added successfully');render('matches')};r.readAsDataURL(file)}else{d.matches.push(m);S(d);alert('Match added successfully');render('matches')}}
function matches(){let d=D();return shell('matches','Manage Matches',`<div class="card"><div class="actions" style="justify-content:space-between"><div><h2 style="margin:0">ALL MATCHES</h2><div class="muted">${d.matches.length} match(es)</div></div><button class="btn primary" onclick="render('add')">＋ ADD MATCH</button></div><div class="tablewrap" style="margin-top:12px"><table class="table"><thead><tr><th>Match</th><th>Category</th><th>Entry</th><th>Prize</th><th>Players</th><th>Start</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.matches.map(m=>`<tr><td><b>${esc(m.title)}</b><br><small class="muted">${esc(m.id)}</small></td><td>${catName(m.category)}</td><td>${money(m.entry)}</td><td>${money(m.prize)}</td><td>${m.players?.length||m.buyers?.length||0}/${m.max||48}</td><td>${fmt(m.startAt)}</td><td><span class="pill ${m.status==='open'?'active':'closed'}">${esc(m.status||'open')}</span></td><td><button class="btn mini blue" onclick="editMatch('${m.id}')">EDIT</button> <button class="btn mini red" onclick="delMatch('${m.id}')">DELETE</button></td></tr>`).join('')||`<tr><td colspan="8"><div class="empty">No matches added.</div></td></tr>`}</tbody></table></div></div>`)}
function editMatch(id){let d=D(),m=d.matches.find(x=>x.id===id);if(!m)return;return shell('matches','Edit Match',`<div class="card"><h2>${esc(m.title)}</h2><form id="editForm" class="formgrid"><div><label class="label">MATCH TITLE</label><input class="input" name="t" value="${esc(m.title)}"></div><div><label class="label">STATUS</label><select class="select" name="status"><option value="open" ${m.status==='open'?'selected':''}>open</option><option value="closed" ${m.status==='closed'?'selected':''}>closed</option></select></div><div><label class="label">START TIME</label><input class="input" name="st" type="datetime-local" value="${dtLocal(m.startAt)}"></div><div><label class="label">ROOM RELEASE TIME</label><input class="input" name="rel" type="datetime-local" value="${dtLocal(m.releaseAt)}"></div><div><label class="label">ROOM ID</label><input class="input" name="ri" value="${esc(m.roomId||'')}"></div><div><label class="label">ROOM PASSWORD</label><input class="input" name="rp" value="${esc(m.roomPass??m.roomPassword??m.password??'')}"></div><div><label class="label">ENTRY FEE</label><input class="input" name="e" type="number" value="${m.entry||0}"></div><div><label class="label">PRIZE POOL</label><input class="input" name="p" type="number" value="${m.prize||0}"></div><div class="full actions"><button class="btn green">SAVE CHANGES</button><button type="button" class="btn ghost" onclick="render('matches')">BACK</button></div></form></div>`);editForm.onsubmit=e=>{e.preventDefault();let f=new FormData(editForm),d2=D(),x=d2.matches.find(a=>a.id===id);Object.assign(x,{title:f.get('t'),status:f.get('status'),startAt:new Date(f.get('st')).getTime(),releaseAt:new Date(f.get('rel')).getTime(),roomId:String(f.get('ri')||'').trim(),roomPass:String(f.get('rp')||'').trim(),roomPassword:String(f.get('rp')||'').trim(),entry:Number(f.get('e')||0),prize:Number(f.get('p')||0)});S(d2);alert('Match updated');render('matches')}}
function delMatch(id){if(!confirm('Delete this match?'))return;let d=D();d.matches=d.matches.filter(x=>x.id!==id);S(d);render('matches')}
function players(){let d=D();return shell('players','Players / Ban-Unban',`<div class="card"><h2>PLAYERS (BAN / UNBAN)</h2><div class="tablewrap"><table class="table"><thead><tr><th>#</th><th>Name</th><th>Gmail</th><th>Level</th><th>Balance</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.users.map((u,i)=>`<tr><td>${i+1}</td><td><b>${esc(u.name)}</b></td><td>${esc(u.email)}</td><td>${u.level||0}</td><td>${money(u.balance)}</td><td><span class="pill ${u.status==='banned'?'banned':'active'}">${u.status==='banned'?'Banned':'Active'}</span></td><td><button class="btn mini ${u.status==='banned'?'green':'red'}" onclick="banUser('${esc(u.email)}')">${u.status==='banned'?'UNBAN':'BAN'}</button></td></tr>`).join('')||`<tr><td colspan="7"><div class="empty">No registered users.</div></td></tr>`}</tbody></table></div></div>`)}
function banUser(em){let d=D(),u=d.users.find(x=>x.email===em);if(!u)return;u.status=u.status==='banned'?'active':'banned';S(d);players()}
function deposits(){let d=D(),rows=d.deposits||[];return shell('deposits','Deposits',`<div class="card"><h2>PENDING DEPOSITS</h2><div class="tablewrap"><table class="table"><thead><tr><th>User</th><th>Method</th><th>Number</th><th>Amount</th><th>Transaction</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.email)}</td><td>${esc(x.method||'bKash')}</td><td>${esc(x.number||'')}</td><td>${money(x.amount)}</td><td>${esc(x.trx||x.trxId||'')}</td><td><span class="pill ${x.status==='pending'?'pending':x.status==='approved'?'active':'banned'}">${esc(x.status)}</span></td><td>${x.status==='pending'?`<button class="btn mini green" onclick="depositAction('${x.id}',1)">APPROVE</button> <button class="btn mini red" onclick="depositAction('${x.id}',0)">REJECT</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="7"><div class="empty">No deposit requests.</div></td></tr>`}</tbody></table></div></div>`)}
function depositAction(id,ok){let d=D(),x=(d.deposits||[]).find(a=>a.id==id);if(!x)return;x.status=ok?'approved':'rejected';if(ok){let u=d.users.find(a=>a.email===x.email);if(u)u.balance=Number(u.balance||0)+Number(x.amount||0)}S(d);deposits()}
function withdraws(){let d=D(),rows=d.withdrawals||[];return shell('withdraws','Withdraws',`<div class="card"><h2>PENDING WITHDRAWS</h2><div class="tablewrap"><table class="table"><thead><tr><th>User</th><th>Method</th><th>Account</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.email||x.uid)}</td><td>${esc(x.method||'bKash')}</td><td>${esc(x.account||x.number||'')}</td><td>${money(x.amount)}</td><td><span class="pill ${x.status==='pending'?'pending':x.status==='approved'?'active':'banned'}">${esc(x.status)}</span></td><td>${x.status==='pending'?`<button class="btn mini green" onclick="withdrawAction('${x.id}',1)">APPROVE</button> <button class="btn mini red" onclick="withdrawAction('${x.id}',0)">REJECT</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">No withdrawal requests.</div></td></tr>`}</tbody></table></div></div>`)}
function withdrawAction(id,ok){let d=D(),x=(d.withdrawals||[]).find(a=>a.id==id);if(!x)return;if(x.status!=='pending')return;if(!ok){let u=d.users.find(a=>a.email===x.email);if(u)u.balance=Number(u.balance||0)+Number(x.amount||0);x.refunded=true}x.status=ok?'approved':'rejected';S(d);withdraws()}
function payment(){let d=D();return shell('payment','Payment Method Settings',`<div class="card"><h2>PAYMENT METHOD SETTINGS</h2><p class="muted">Method enable করলে User Panel-এ সেই method, আপনার দেওয়া number এবং আপনার দেওয়া background color দেখাবে।</p>${['bkash','nagad','rocket'].map(k=>{let s=d.settings[k];return `<div class="setting"><div class="row"><div><b>${k.toUpperCase()}</b><br><small class="muted">Number: ${esc(s.number||'Not set')}</small></div><button class="switch ${s.available?'on':''}" onclick="togglePay('${k}')">${s.available?'ENABLED':'DISABLED'}</button></div><div class="actions" style="margin-top:9px;flex-wrap:wrap"><input id="num_${k}" class="input" style="max-width:280px" value="${esc(s.number||'')}" placeholder="${k} number"><input id="color_${k}" type="color" value="${esc(s.color||'#7b4dff')}" style="width:58px;height:44px;padding:3px;border-radius:10px;background:#111;border:1px solid #444"><button class="btn ghost mini" onclick="savePay('${k}')">SAVE NUMBER + COLOR</button></div></div>`}).join('')}<div class="card" style="margin-top:14px"><h3>AUTO PAYMENT</h3><p class="muted">Auto payment যোগ করা যাবে, তবে এর জন্য bKash/Nagad/Rocket-এর অনুমোদিত payment gateway/API এবং secure backend/server লাগবে। এই standalone HTML-এ সরাসরি real auto-payment করা নিরাপদ/সম্ভব নয়।</p></div></div>`)}
function togglePay(k){let d=D();d.settings[k].available=!d.settings[k].available;S(d);payment()}
function savePay(k){let d=D();d.settings[k].number=document.getElementById('num_'+k).value.trim();d.settings[k].color=document.getElementById('color_'+k).value;S(d);alert(k.toUpperCase()+' number and color saved');payment()}
function images(){let d=D(),bl=(d.images&&d.images.bannerLink)||'';return shell('images','Manage Category Images',`<div class="card"><h2>MANAGE PLAY BANNER & CATEGORY IMAGES</h2><p class="muted">Play page-এর category-এর ঠিক উপরের banner এবং প্রতিটি category card-এর image এখান থেকে change করতে পারবে। Banner-এ tap করলে যে link খুলবে সেটি নিচে optional ভাবে দিতে পারবে। URL না দিলে banner শুধু image হিসেবে থাকবে, কোনো link open হবে না।</p><div class="imagegrid"><div class="imagebox" style="grid-column:1/-1"><b>PLAY PAGE BANNER</b><img src="${imgFor(d,'banner')}" style="width:100%;max-height:220px;object-fit:cover;border-radius:14px;margin-top:8px"><input class="file" type="file" accept="image/*" onchange="saveImg('banner',this)"><label class="label" style="display:block;margin-top:10px">BANNER CLICK URL (OPTIONAL)</label><input id="bannerLink" class="input" value="${esc(bl)}" placeholder="https://example.com অথবা https://t.me/yourusername"><div class="actions" style="margin-top:9px"><button class="btn primary" onclick="saveBannerLink()">SAVE BANNER URL</button><button class="btn ghost" onclick="clearBannerLink()">REMOVE LINK</button></div><small class="muted">URL না দিলে User Panel-এ banner-এ tap করলেও কিছু open হবে না।</small></div>${CATS.map(c=>`<div class="imagebox"><b>${c[1]}</b><img src="${imgFor(d,c[0])}"><input class="file" type="file" accept="image/*" onchange="saveImg('${c[0]}',this)"></div>`).join('')}</div></div>`)}
function saveImg(k,input){let f=input.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{let d=D();d.images=d.images||{};d.images[k]=r.result;S(d);alert(k==='banner'?'Play banner updated':'Category image updated');images()};r.readAsDataURL(f)}
function saveBannerLink(){let d=D();d.images=d.images||{};let v=(document.getElementById('bannerLink')?.value||'').trim();if(v&&!/^https?:\/\//i.test(v))v='https://'+v;d.images.bannerLink=v;S(d);alert(v?'Banner URL saved.':'Banner URL removed.');images()}
function clearBannerLink(){let d=D();d.images=d.images||{};d.images.bannerLink='';S(d);images()}
