function fmt(t){if(!t)return '—';return new Date(t).toLocaleString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function dtLocal(t){if(!t)return '';let d=new Date(t-Date.parse('1970-01-01T00:00:00Z')+0); // fallback below
let x=new Date(t);let p=n=>String(n).padStart(2,'0');return x.getFullYear()+'-'+p(x.getMonth()+1)+'-'+p(x.getDate())+'T'+p(x.getHours())+':'+p(x.getMinutes())}

function redeem(){let d=D(),rs=d.redeems||[];return shell('redeem','Redeem Codes',`<div class="card"><h2>REDEEM CODE</h2><p class="muted">একটি code বানিয়ে নির্দিষ্ট টাকা দেওয়া যাবে। MAX USES = 1 দিলে শুধু ১ জন ব্যবহার করতে পারবে। বেশি দিলে যতজন সেট করা হবে ততজন আলাদা user একবার করে redeem করতে পারবে।</p><div class="formgrid"><div><label class="label">AMOUNT (৳)</label><input id="rdAmount" class="input" type="number" min="1" placeholder="100"></div><div><label class="label">MAX USERS</label><input id="rdUses" class="input" type="number" min="1" value="1" placeholder="1"></div><div class="full"><label class="label">CUSTOM REDEEM CODE (OPTIONAL)</label><input id="rdCode" class="input" placeholder="Leave blank to generate automatically"></div><div class="full actions"><button class="btn primary" onclick="createRedeem()">CREATE REDEEM CODE</button></div></div></div><div class="card section"><h3>REDEEM CODE LIST</h3><div class="tablewrap"><table class="table"><thead><tr><th>Code</th><th>Amount</th><th>Used</th><th>Max Users</th><th>Status</th><th>Action</th></tr></thead><tbody>${rs.slice().reverse().map(x=>{let used=(x.redeemedBy||[]).length,closed=!!x.cancelled||used>=Number(x.maxUses||1);return `<tr><td><b>${esc(x.code)}</b></td><td>${money(x.amount)}</td><td>${used}</td><td>${x.maxUses||1}</td><td><span class="pill ${closed?'closed':'active'}">${x.cancelled?'CANCELLED':closed?'FULL':'ACTIVE'}</span></td><td>${closed?'—':`<button class="btn mini red" onclick="cancelRedeem('${esc(x.code)}')">CANCEL</button>`}</td></tr>`}).join('')||`<tr><td colspan="6"><div class="empty">No redeem codes created.</div></td></tr>`}</tbody></table></div></div>`)}
function createRedeem(){let d=D(),amount=+(document.getElementById('rdAmount')||{}).value||0,maxUses=Math.max(1,Math.floor(+(document.getElementById('rdUses')||{}).value||1)),custom=((document.getElementById('rdCode')||{}).value||'').trim().toUpperCase();if(amount<=0)return alert('Valid amount দিন');d.redeems=d.redeems||[];let code=custom||('REDEEM-'+Math.random().toString(36).slice(2,8).toUpperCase()+'-'+Date.now().toString(36).slice(-4).toUpperCase());if(d.redeems.some(x=>x.code===code))return alert('এই code আগে থেকেই আছে');d.redeems.push({id:Date.now(),amount,code,maxUses,redeemedBy:[],cancelled:false,createdAt:Date.now()});S(d);alert('Redeem code তৈরি হয়েছে: '+code);redeem()}
function cancelRedeem(code){let d=D(),x=(d.redeems||[]).find(a=>a.code===code);if(!x)return;x.cancelled=true;S(d);redeem()}

function deduct(){let d=D(),hs=d.deductions||[];return shell('deduct','Deduct Money',`<div class="card"><h2>DEDUCT MONEY FROM USER</h2><p class="muted">ভুল করে কোনো user-কে টাকা দিলে এখান থেকে তার balance থেকে টাকা কেটে দিতে পারবে। একই user-এর Gmail, নাম এবং বর্তমান balance নিচে দেখা যাবে।</p><div class="tablewrap"><table class="table"><thead><tr><th>User Name</th><th>Gmail</th><th>Current Balance</th><th>Action</th></tr></thead><tbody>${d.users.map(u=>`<tr><td><b>${esc(u.name||'—')}</b></td><td>${esc(u.email)}</td><td><b>${money(u.balance||0)}</b></td><td><button class="btn mini red" onclick="openDeduct('${esc(u.email)}')">DEDUCT</button></td></tr>`).join('')||`<tr><td colspan="4"><div class="empty">No users registered.</div></td></tr>`}</tbody></table></div></div><div class="card section"><h3>DEDUCT HISTORY</h3><div class="tablewrap"><table class="table"><thead><tr><th>User</th><th>Amount</th><th>Note</th><th>Date</th></tr></thead><tbody>${hs.slice().reverse().map(x=>`<tr><td>${esc(x.name||'—')}<br><small class="muted">${esc(x.email)}</small></td><td>${money(x.amount)}</td><td>${esc(x.note||'—')}</td><td>${fmt(x.createdAt)}</td></tr>`).join('')||`<tr><td colspan="4"><div class="empty">No deductions yet.</div></td></tr>`}</tbody></table></div></div>`)}
function openDeduct(email){let d=D(),u=d.users.find(x=>x.email===email);if(!u)return alert('User পাওয়া যায়নি');let current=Number(u.balance||0);let amount=prompt((u.name||'User')+'\nGmail: '+u.email+'\nCurrent Balance: '+money(current)+'\n\nকত টাকা কাটবেন?', '');if(amount===null)return;amount=Number(amount);if(!Number.isFinite(amount)||amount<=0)return alert('Valid amount দিন');if(amount>current)return alert('User-এর balance-এর চেয়ে বেশি টাকা কাটা যাবে না');let note=prompt('Deduct note / কারণ লিখুন (optional):','Wrong transfer / correction');if(note===null)note='';if(!confirm((u.name||u.email)+' এর balance থেকে '+money(amount)+' কাটবেন?'))return;u.balance=current-amount;d.deductions=d.deductions||[];d.deductions.push({id:Date.now(),email:u.email,name:u.name||'',amount,note:note.trim(),createdAt:Date.now()});S(d);alert(money(amount)+' কেটে নেওয়া হয়েছে। নতুন balance: '+money(u.balance));deduct()}
function deductMoney(email){let d=D(),u=d.users.find(x=>x.email===email);if(!u)return alert('User পাওয়া যায়নি');let amount=+(document.getElementById('dedAmount')||{}).value||0,note=((document.getElementById('dedNote')||{}).value||'').trim();let bal=Number(u.balance||0);if(amount<=0)return alert('Valid amount দিন');if(amount>bal)return alert('User-এর balance-এর চেয়ে বেশি টাকা কাটা যাবে না');if(!confirm((u.name||u.email)+' এর balance থেকে '+money(amount)+' কাটবেন?'))return;u.balance=bal-amount;d.deductions=d.deductions||[];d.deductions.push({id:Date.now(),email:u.email,name:u.name||'',amount,note,createdAt:Date.now()});S(d);closeM();alert(money(amount)+' কেটে নেওয়া হয়েছে। নতুন balance: '+money(u.balance));deduct()}
function give(){let d=D(),gs=d.gifts||[];return shell('give','Give Money',`<div class="card"><h2>GIVE MONEY TO USER</h2><p class="muted">এখানে কোনো redeem code ছাড়াই Admin সরাসরি যেকোনো user-এর balance-এ যত টাকা চান দিতে পারবেন। এটি আলাদা হিসাব হিসেবে থাকবে।</p><div class="formgrid"><div><label class="label">SELECT USER</label><select id="gvUser" class="select">${d.users.map(u=>`<option value="${esc(u.email)}">${esc(u.name)} — ${esc(u.email)}</option>`).join('')}</select></div><div><label class="label">AMOUNT (৳)</label><input id="gvAmount" class="input" type="number" min="1" placeholder="100"></div><div class="full"><label class="label">NOTE (OPTIONAL)</label><input id="gvNote" class="input" placeholder="Gift / Bonus / Prize"></div><div class="full actions"><button class="btn primary" onclick="giveMoney()">GIVE MONEY</button></div></div></div><div class="card section"><h3>GIVEN MONEY HISTORY</h3><div class="tablewrap"><table class="table"><thead><tr><th>User</th><th>Amount</th><th>Note</th><th>Date</th></tr></thead><tbody>${gs.slice().reverse().map(x=>`<tr><td>${esc(x.email)}</td><td>${money(x.amount)}</td><td>${esc(x.note||'—')}</td><td>${fmt(x.createdAt)}</td></tr>`).join('')||`<tr><td colspan="4"><div class="empty">No direct credits yet.</div></td></tr>`}</tbody></table></div></div>`)}
function giveMoney(){let d=D(),email=(document.getElementById('gvUser')||{}).value||'',amount=+(document.getElementById('gvAmount')||{}).value||0,note=((document.getElementById('gvNote')||{}).value||'').trim();if(!email||amount<=0)return alert('User এবং valid amount দিন');let u=d.users.find(a=>a.email===email);if(!u)return alert('User পাওয়া যায়নি');u.balance=Number(u.balance||0)+amount;d.gifts=d.gifts||[];d.gifts.push({id:Date.now(),email,amount,note,createdAt:Date.now()});S(d);alert(money(amount)+' user balance-এ যোগ হয়েছে।');give()}

